-- Synthetic accounts only. Automatic assignment must be atomic with the claim.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select set_config('test.auto_spent',(select spent::text from private.photo_credit_wallets where account_id='20000000-0000-4000-8000-000000000001'),true);
select set_config('test.auto_allowance',(select coalesce(allowance::text,'unlimited') from private.photo_credit_wallets where account_id='20000000-0000-4000-8000-000000000001'),true);
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000010',true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000010","role":"authenticated","aal":"aal1"}',true);
select public.postcard_create_shop('20000000-0000-4000-8000-000000000001','Auto shop A','','a9000000-0000-4000-8000-000000000001');
select public.postcard_create_shop('20000000-0000-4000-8000-000000000001','Auto shop B','','a9000000-0000-4000-8000-000000000002');
select public.postcard_create_batch('20000000-0000-4000-8000-000000000001','milka-gift','Auto assignment fixture',6,'a9000000-0000-4000-8000-000000000003');
select set_config('test.auto_batch',(select id::text from public.postcard_batches where request_id='a9000000-0000-4000-8000-000000000003'),true);
select public.postcard_prepare_batch('20000000-0000-4000-8000-000000000001',current_setting('test.auto_batch')::uuid);
select set_config('test.auto_project',(select project_id::text from public.postcard_batches where id=current_setting('test.auto_batch')::uuid),true);
select set_config('test.auto_group',(select group_id::text from public.postcard_batches where id=current_setting('test.auto_batch')::uuid),true);
reset role;
update private.postcard_shop_secrets set activation_pin=case shop_id when 'a9000000-0000-4000-8000-000000000001' then '0042' else '0055' end where shop_id in ('a9000000-0000-4000-8000-000000000001','a9000000-0000-4000-8000-000000000002');
select set_config('test.auto_legacy',(select activation_code from private.postcard_shop_secrets where shop_id='a9000000-0000-4000-8000-000000000001'),true);
insert into public.postcard_shops(id,account_id,name) values('a9000000-0000-4000-8000-000000000004','20000000-0000-4000-8000-000000000002','Other account shop');
insert into private.postcard_shop_secrets(shop_id,activation_code,activation_pin) values('a9000000-0000-4000-8000-000000000004','ABCDEF123456','9001');
-- Force an insert collision: the trigger chooses another PIN, keeping every existing code.
insert into public.postcard_shops(id,account_id,name) values('a9000000-0000-4000-8000-000000000005','20000000-0000-4000-8000-000000000001','New colliding shop');
insert into private.postcard_shop_secrets(shop_id,activation_code,activation_pin) values('a9000000-0000-4000-8000-000000000005','ABCDEF654321','0042');
select isnt((select activation_pin from private.postcard_shop_secrets where shop_id='a9000000-0000-4000-8000-000000000005'),'0042','new shops do not reuse an existing account PIN');
select is((select activation_pin from private.postcard_shop_secrets where shop_id='a9000000-0000-4000-8000-000000000001'),'0042','existing leading-zero code is never rotated');
insert into public.media_assets(id,account_id,project_id,group_id,kind,storage_bucket,storage_path,original_file_name,mime_type,size_bytes,sha256,version,metadata,created_by)
select ('a9100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20000000-0000-4000-8000-000000000001',current_setting('test.auto_project')::uuid,current_setting('test.auto_group')::uuid,'marker','markers-private','auto-test/'||n||'.png','card.png','image/png',2048,repeat('b',64),n,'{"width":1200,"height":1800,"exifStripped":true}','10000000-0000-4000-8000-000000000010' from generate_series(1,5)n;
set local role authenticated;
select public.postcard_attach_print_marker('20000000-0000-4000-8000-000000000001',c.id,('a9100000-0000-4000-8000-'||lpad(c.ordinal::text,12,'0'))::uuid) from public.postcard_cards c where batch_id=current_setting('test.auto_batch')::uuid and ordinal<=5;
select public.postcard_move_cards('20000000-0000-4000-8000-000000000001','assign','a9000000-0000-4000-8000-000000000002',array(select id from public.postcard_cards where batch_id=current_setting('test.auto_batch')::uuid and ordinal=2),'a9000000-0000-4000-8000-000000000006');
reset role;
select set_config('test.auto_token_'||ordinal,public_token,true) from public.postcard_cards where batch_id=current_setting('test.auto_batch')::uuid;
set local role service_role;
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claim.role','service_role',true);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.postcard_buyer_state(current_setting('test.auto_token_1'),null)->'card'->>'state','available','prepared stock card displays the code entry form');
select is(public.postcard_buyer_state(current_setting('test.auto_token_6'),null)->'card'->>'state','unavailable','a card without canonical artwork stays blocked');
select is(public.postcard_buyer_claim(current_setting('test.auto_token_1'),'999999',repeat('1',64))->>'error','invalid_card','bad code cannot auto-assign');
select is(public.postcard_buyer_claim(current_setting('test.auto_token_1'),'9001',repeat('1',64))->>'error','invalid_card','a different account code cannot claim stock');
reset role;
select ok((select shop_id is null from public.postcard_cards where public_token=current_setting('test.auto_token_1')),'failed claims leave stock unassigned');
update private.postcard_shop_secrets set activation_pin='0042' where shop_id='a9000000-0000-4000-8000-000000000002';
set local role service_role;
select is(public.postcard_buyer_claim(current_setting('test.auto_token_1'),'0042',repeat('1',64))->>'error','invalid_card','legacy duplicate PINs are rejected rather than choosing a shop');
reset role;
update private.postcard_shop_secrets set activation_pin='0055' where shop_id='a9000000-0000-4000-8000-000000000002';
set local role service_role;
select is(public.postcard_buyer_claim(current_setting('test.auto_token_1'),'0042',repeat('1',64))->>'owned','true','valid PIN activates prepared stock');
select is(public.postcard_buyer_claim(current_setting('test.auto_token_1'),'0042',repeat('1',64))->>'owned','true','same personal capability retries idempotently');
select is(public.postcard_buyer_claim(current_setting('test.auto_token_1'),'0055',repeat('2',64))->>'error','invalid_card','another buyer cannot take an existing claim');
select is(public.postcard_buyer_claim(current_setting('test.auto_token_2'),'0042',repeat('2',64))->>'error','invalid_card','assigned card never accepts another shop code');
select is(public.postcard_buyer_claim(current_setting('test.auto_token_2'),'0055',repeat('2',64))->>'owned','true','previous manual handoffs continue working');
select is(public.postcard_buyer_claim(current_setting('test.auto_token_3'),current_setting('test.auto_legacy'),repeat('3',64))->>'owned','true','previously issued 12-character inserts also route stock');
select is(public.postcard_buyer_claim(current_setting('test.auto_token_6'),'0042',repeat('6',64))->>'error','invalid_card','PIN cannot replace missing canonical print');
reset role;
select is((select shop_id from public.postcard_cards where public_token=current_setting('test.auto_token_1')),'a9000000-0000-4000-8000-000000000001'::uuid,'card binds to the matching account shop');
select ok((select bool_and(sold_at is null) from public.postcard_cards where batch_id=current_setting('test.auto_batch')::uuid),'no sale is inferred from activation');
select is((select count(*)::int from public.postcard_movements where origin='buyer_code' and card_ids&&array(select id from public.postcard_cards where batch_id=current_setting('test.auto_batch')::uuid)),2,'each automatic handoff is counted once');
select ok((select bool_and(actor_user_id is null) from public.postcard_movements where origin='buyer_code' and card_ids&&array(select id from public.postcard_cards where batch_id=current_setting('test.auto_batch')::uuid)),'automatic handoffs never impersonate a manager');
select is((select count(*)::int from public.audit_logs where action='postcard.cards.auto_assigned' and entity_id in(select id from public.postcard_movements where origin='buyer_code' and card_ids&&array(select id from public.postcard_cards where batch_id=current_setting('test.auto_batch')::uuid))),2,'automatic handoffs have their own audit records');
select is((select spent from private.photo_credit_wallets where account_id='20000000-0000-4000-8000-000000000001'),current_setting('test.auto_spent')::bigint+3,'claims and retry consume exactly three creations');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000010',true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000010","role":"authenticated","aal":"aal1"}',true);
select is((select value->>'delivered' from jsonb_array_elements(public.postcard_shop_report('20000000-0000-4000-8000-000000000001')) where value->>'shopId'='a9000000-0000-4000-8000-000000000001'),'2','shop report includes both automatic handoffs');
select is((select value->>'stock' from jsonb_array_elements(public.postcard_shop_report('20000000-0000-4000-8000-000000000001')) where value->>'shopId'='a9000000-0000-4000-8000-000000000001'),'2','activated cards remain in shop stock until a real sale');
select is((select value->>'sold' from jsonb_array_elements(public.postcard_shop_report('20000000-0000-4000-8000-000000000001')) where value->>'shopId'='a9000000-0000-4000-8000-000000000001'),'0','automatic handoffs do not inflate sales report');
reset role;
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claim.role','service_role',true);
select set_config('request.jwt.claims','{"role":"service_role"}',true);

update private.photo_credit_wallets set allowance=spent where account_id='20000000-0000-4000-8000-000000000001';
set local role service_role;
select is(public.postcard_buyer_claim(current_setting('test.auto_token_4'),'0042',repeat('4',64))->>'error','activation_unavailable','empty credit wallet blocks activation before a handoff');
reset role;
select ok((select shop_id is null and ar_item_id is null from public.postcard_cards where public_token=current_setting('test.auto_token_4')),'quota failure leaves both stock and ownership intact');
update private.photo_credit_wallets set allowance=case when current_setting('test.auto_allowance')='unlimited' then null else current_setting('test.auto_allowance')::bigint end where account_id='20000000-0000-4000-8000-000000000001';
update public.groups set archived_at=statement_timestamp() where id=current_setting('test.auto_group')::uuid;
set local role service_role;
select is(public.postcard_buyer_claim(current_setting('test.auto_token_5'),'0042',repeat('5',64))->>'error','activation_unavailable','archived groups still reject activation');
reset role;
select ok((select shop_id is null from public.postcard_cards where public_token=current_setting('test.auto_token_5')),'archive failure creates no inventory handoff');
select ok(not has_function_privilege('authenticated','public.postcard_buyer_claim(text,text,text)','execute'),'ordinary sessions cannot bypass the gateway');
select ok(not has_function_privilege('anon','public.postcard_buyer_claim(text,text,text)','execute'),'anonymous direct claims remain forbidden');
select throws_ok($$insert into public.postcard_movements(account_id,request_id,kind,shop_id,card_ids,actor_user_id,origin) values('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'sell','a9000000-0000-4000-8000-000000000001',array[(select id from public.postcard_cards where public_token=current_setting('test.auto_token_1'))],null,'buyer_code')$$,'23514',null,'the purchaser origin cannot create a sale');
select * from finish();
rollback;
